! ============================================================
! VML 文件系统扩展库 — Fortran
!
! 使用示例:
!   call asm("SYSCALL 340")   ! 创建目录
!   call asm("SYSCALL 341")   ! 删除文件/目录
!   call asm("SYSCALL 342")   ! 重命名
!   call asm("SYSCALL 343")   ! 读取目录
!   call asm("SYSCALL 344")   ! 获取文件状态
!
! 注意: 仅在 OS 模式 (--mode os) 下可用
! ============================================================

! ============================================================
! SYSCALL 340 — MkDir
! 创建目录
! 参数: R0 = 目录路径地址 (\0 结尾)
! 返回: R0 = 0 成功, <0 失败
!
! Fortran 使用示例:
!   ! 创建目录 "/tmp/mydir"
!   ! R0 = 路径字符串地址
!   call asm("SYSCALL 340")
! ============================================================

! ============================================================
! SYSCALL 341 — Remove
! 删除文件或目录
! 参数: R0 = 路径地址 (\0 结尾)
! 返回: R0 = 0 成功, <0 失败
!
! Fortran 使用示例:
!   ! 删除文件 "temp.txt"
!   ! R0 = 路径字符串地址
!   call asm("SYSCALL 341")
! ============================================================

! ============================================================
! SYSCALL 342 — Rename
! 重命名文件或目录
! 参数:
!   R0 = 旧路径地址 (\0 结尾)
!   R1 = 新路径地址 (\0 结尾)
! 返回: R0 = 0 成功, <0 失败
!
! Fortran 使用示例:
!   ! 将 "old.txt" 重命名为 "new.txt"
!   ! R0 = "old.txt\0" 的地址
!   ! R1 = "new.txt\0" 的地址
!   call asm("SYSCALL 342")
! ============================================================

! ============================================================
! SYSCALL 343 — ReadDir
! 读取目录中的文件列表
! 参数:
!   R0 = 目录路径地址 (\0 结尾)
!   R1 = 缓冲区地址 (文件名地址数组)
! 返回: R0 = 文件数量, <0 失败
!
! 注意: 当前为 stub
! ============================================================

! ============================================================
! SYSCALL 344 — Stat
! 获取文件状态信息 (大小、权限、修改时间等)
! 参数:
!   R0 = 文件路径地址 (\0 结尾)
!   R1 = 状态信息缓冲区地址
! 返回: R0 = 0 成功, <0 失败
!
! 注意: 当前为 stub
! ============================================================

! ============================================================
! 通用文件操作也可使用 110-114 的 FileOpen/FileRead/FileWrite
! FS 操作也可通过 Device SYSCALL (100-104) 以 "fs" 设备访问
! ============================================================
